package com.gogleox.scrip.shop;

import com.gogleox.scrip.account.*;
import com.gogleox.scrip.ledger.AccountLedger;
import com.gogleox.scrip.payment.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

/** Durable provider implementation; it coordinates money only and never observes inventory mutation. */
public final class DefaultShopEconomyPort implements ShopEconomyPort {
    private final AccountLedger ledger; private final PaymentService payments; private final Clock clock;
    public DefaultShopEconomyPort(AccountLedger ledger){this(ledger,Clock.systemUTC());}
    DefaultShopEconomyPort(AccountLedger ledger,Clock clock){this.ledger=Objects.requireNonNull(ledger);this.payments=new PaymentService(ledger);this.clock=Objects.requireNonNull(clock);}
    @Override public int apiVersion(){return API_VERSION;}
    @Override public CompletionStage<ShopQuoteResult> quote(ShopQuoteRequest request){PaymentResult result=payments.preview(request.actorId(),request.buyer(),request.seller(),request.serverPrice());if(result.status()!=PaymentResult.Status.PREVIEW_READY)return CompletableFuture.completedFuture(new ShopQuoteResult(mapQuote(result.status()),Optional.empty()));ShopQuote quote=new ShopQuote(UUID.randomUUID(),request.actorId(),result.preview().orElseThrow(),request.priceReference());return CompletableFuture.completedFuture(new ShopQuoteResult(quote.payment().confirmationRequired()?ShopQuoteResult.Status.CONFIRMATION_REQUIRED:ShopQuoteResult.Status.READY,Optional.of(quote)));}
    @Override public CompletionStage<SettlementResult> reserve(String id,ShopQuote quote,boolean buyerConfirmed){if(!validId(id))return CompletableFuture.completedFuture(result(SettlementResult.Status.INVALID,null));Optional<ShopSettlement> prior=ledger.shopSettlement(id);if(prior.isPresent())return CompletableFuture.completedFuture(result(prior.get().actorId().equals(quote.actorId())&&prior.get().buyer().equals(quote.payment().source())&&prior.get().seller().equals(quote.payment().destination())&&prior.get().amount()==quote.payment().amount()?SettlementResult.Status.DUPLICATE:SettlementResult.Status.INVALID,prior.get()));PaymentResult authorization=payments.authorizeSettlement(quote.actorId(),quote.payment(),buyerConfirmed);if(authorization.status()==PaymentResult.Status.CONFIRMATION_REQUIRED)return CompletableFuture.completedFuture(result(SettlementResult.Status.CONFIRMATION_REQUIRED,null));if(authorization.status()!=PaymentResult.Status.PREVIEW_READY)return CompletableFuture.completedFuture(result(mapPayment(authorization.status()),null));ShopSettlement settlement=new ShopSettlement(id,quote.actorId(),quote.payment().source(),quote.payment().destination(),quote.payment().amount(),quote.payment().fee(),quote.payment().policyRevision(),quote.payment().expiresAt(),UUID.randomUUID(),UUID.randomUUID(),SettlementState.RESERVED);return ledger.reserveShopSettlement(UUID.randomUUID(),settlement).handle((saved,error)->error==null?result(SettlementResult.Status.RESERVED,saved):result(SettlementResult.Status.UNAUTHORIZED,null));}
    @Override public CompletionStage<SettlementResult> settle(String id,boolean deliveryConfirmed){Optional<ShopSettlement> lookup=ledger.shopSettlement(id);if(lookup.isEmpty())return CompletableFuture.completedFuture(result(SettlementResult.Status.NOT_FOUND,null));ShopSettlement settlement=lookup.get();if(settlement.state()==SettlementState.SETTLED)return CompletableFuture.completedFuture(result(SettlementResult.Status.DUPLICATE,settlement));if(settlement.state()!=SettlementState.RESERVED)return CompletableFuture.completedFuture(result(settlement.state()==SettlementState.CANCELLED?SettlementResult.Status.CANCELLED:SettlementResult.Status.INVALID,settlement));if(!clock.instant().isBefore(settlement.expiresAt()))return cancelExpired(settlement);if(!deliveryConfirmed)return cancelOrRefund(id,"delivery not confirmed");return ledger.executePayment(settlement.paymentOperationId(),settlement.actorId(),settlement.buyer(),settlement.seller(),settlement.amount(),settlement.fee(),settlement.policyRevision()).thenCompose(outcome->{if(outcome.status()!=TransferOutcome.Status.SUCCESS)return CompletableFuture.completedFuture(result(mapTransfer(outcome.status()),ledger.shopSettlement(id).orElse(settlement)));return ledger.transitionShopSettlement(UUID.randomUUID(),id,SettlementState.RESERVED,SettlementState.SETTLED).thenApply(saved->result(SettlementResult.Status.SETTLED,saved));});}
    @Override public CompletionStage<SettlementResult> cancelOrRefund(String id,String reason){Optional<ShopSettlement> lookup=ledger.shopSettlement(id);if(lookup.isEmpty())return CompletableFuture.completedFuture(result(SettlementResult.Status.NOT_FOUND,null));ShopSettlement settlement=lookup.get();if(settlement.state()==SettlementState.RESERVED)return ledger.transitionShopSettlement(UUID.randomUUID(),id,SettlementState.RESERVED,SettlementState.CANCELLED).thenApply(saved->result(SettlementResult.Status.CANCELLED,saved));if(settlement.state()==SettlementState.REFUNDED)return CompletableFuture.completedFuture(result(SettlementResult.Status.DUPLICATE,settlement));if(settlement.state()!=SettlementState.SETTLED&&settlement.state()!=SettlementState.REFUND_PENDING)return CompletableFuture.completedFuture(result(SettlementResult.Status.INVALID,settlement));CompletionStage<ShopSettlement> pending=settlement.state()==SettlementState.SETTLED?ledger.transitionShopSettlement(UUID.randomUUID(),id,SettlementState.SETTLED,SettlementState.REFUND_PENDING):CompletableFuture.completedFuture(settlement);return pending.thenCompose(value->ledger.refundShopSettlement(value).thenCompose(outcome->{if(outcome.status()==TransferOutcome.Status.SUCCESS)return ledger.transitionShopSettlement(UUID.randomUUID(),id,SettlementState.REFUND_PENDING,SettlementState.REFUNDED).thenApply(saved->result(SettlementResult.Status.REFUNDED,saved));return ledger.transitionShopSettlement(UUID.randomUUID(),id,SettlementState.REFUND_PENDING,SettlementState.REQUIRES_RECONCILIATION).thenApply(saved->result(SettlementResult.Status.REQUIRES_RECONCILIATION,saved));}));}
    @Override public CompletionStage<SettlementResult> getSettlement(String id){Optional<ShopSettlement> lookup=ledger.shopSettlement(id);if(lookup.isEmpty())return CompletableFuture.completedFuture(result(SettlementResult.Status.NOT_FOUND,null));ShopSettlement settlement=lookup.get();if(settlement.state()==SettlementState.RESERVED&&!clock.instant().isBefore(settlement.expiresAt()))return cancelExpired(settlement);return CompletableFuture.completedFuture(result(status(settlement.state()),settlement));}
    private CompletionStage<SettlementResult> cancelExpired(ShopSettlement settlement){return ledger.transitionShopSettlement(UUID.randomUUID(),settlement.id(),SettlementState.RESERVED,SettlementState.CANCELLED).thenApply(saved->result(SettlementResult.Status.EXPIRED,saved));}
    private static boolean validId(String id){return id!=null&&id.matches("[A-Za-z0-9._:-]{1,96}");} private static SettlementResult result(SettlementResult.Status status,ShopSettlement settlement){return new SettlementResult(status,Optional.ofNullable(settlement));} private static SettlementResult.Status status(SettlementState state){return switch(state){case RESERVED->SettlementResult.Status.RESERVED;case SETTLED->SettlementResult.Status.SETTLED;case CANCELLED->SettlementResult.Status.CANCELLED;case REFUNDED->SettlementResult.Status.REFUNDED;case REFUND_PENDING,REQUIRES_RECONCILIATION->SettlementResult.Status.REQUIRES_RECONCILIATION;default->SettlementResult.Status.INVALID;};} private static ShopQuoteResult.Status mapQuote(PaymentResult.Status status){return switch(status){case UNAUTHORIZED,FROZEN->ShopQuoteResult.Status.UNAUTHORIZED;case INSUFFICIENT_FUNDS->ShopQuoteResult.Status.INSUFFICIENT_FUNDS;case INVALID_AMOUNT->ShopQuoteResult.Status.INVALID;default->ShopQuoteResult.Status.FAILURE;};} private static SettlementResult.Status mapPayment(PaymentResult.Status status){return switch(status){case UNAUTHORIZED,FROZEN->SettlementResult.Status.UNAUTHORIZED;case INSUFFICIENT_FUNDS->SettlementResult.Status.INSUFFICIENT_FUNDS;default->SettlementResult.Status.INVALID;};} private static SettlementResult.Status mapTransfer(TransferOutcome.Status status){return switch(status){case INSUFFICIENT_FUNDS->SettlementResult.Status.INSUFFICIENT_FUNDS;case FROZEN_ACCOUNT,UNAUTHORIZED->SettlementResult.Status.UNAUTHORIZED;default->SettlementResult.Status.STORAGE_FAILURE;};}
}
